mapper.select:
SELECT grade_id, exam_id, student_id, score, rank_no, comment, created_at, updated_at
  FROM grades
 WHERE exam_id = #{examId} AND student_id = #{studentId}

SELECT exam_id
FROM grades
WHERE grade_id = #{gradeId}

SELECT total_score
FROM exams
WHERE exam_id = #{examId}

SELECT e.exam_id, -- 시험 ID e.exam_name, -- 시험명 e.subject, -- 과목명 e.exam_date, -- 시험일 g.student_id, -- 학생 ID u.name AS student_name, -- 학생 이름 s.student_no, -- 학생 관리번호 g.score, -- 점수 e.total_score -- 만점 FROM grades g JOIN exams e ON e.exam_id = g.exam_id JOIN students s ON s.student_id = g.student_id JOIN users u ON u.user_id = s.user_id WHERE g.student_id = #{studentId}
AND e.subject = #{subject}
ORDER BY e.exam_date ASC, e.exam_id ASC

SELECT EXISTS (
    SELECT 1
    FROM student_parents sp
    JOIN parents p ON p.parent_id = sp.parent_id
    JOIN users u ON u.user_id = p.user_id
    WHERE u.login_id = #{loginId}
    AND sp.student_id = #{studentId}
)

SELECT e.exam_name, e.subject, e.exam_date, e.total_score, c.class_name, g.score, g.rank_no, ( SELECT COUNT(*) FROM grades gr WHERE gr.exam_id = g.exam_id ) AS rank_total, g.comment, u.name AS student_name, s.student_no FROM grades g JOIN exams e ON e.exam_id = g.exam_id JOIN classes c ON c.class_id = e.class_id JOIN students s ON s.student_id = g.student_id JOIN users u ON u.user_id = s.user_id WHERE g.student_id = #{studentId}
AND e.subject = #{subject}
ORDER BY e.exam_date DESC, e.exam_id DESC

SELECT e.exam_id, -- 시험 ID e.exam_name, -- 시험명 e.subject, -- 과목명 e.exam_date, -- 시험일시 c.class_id, -- 반 ID c.class_name, -- 반 이름 ROUND(AVG(g.score), 1) AS score, -- 시험별 반 평균 점수 e.total_score, -- 만점 COUNT(g.grade_id) AS grade_count -- 입력된 성적 수 FROM exams e JOIN classes c ON c.class_id = e.class_id JOIN grades g ON g.exam_id = e.exam_id WHERE e.class_id = #{classId}
AND e.subject ILIKE CONCAT('%', #{subject}, '%')
GROUP BY e.exam_id, e.exam_name, e.subject, e.exam_date, c.class_id, c.class_name, e.total_score ORDER BY e.exam_date ASC, e.exam_id ASC

SELECT DISTINCT e.subject FROM grades g JOIN exams e ON e.exam_id = g.exam_id
e.subject IS NOT NULL AND e.subject != ''
AND g.student_id = #{studentId}
AND e.class_id = #{classId}
ORDER BY e.subject

SELECT e.subject, -- 과목명 e.exam_id, -- 시험 ID e.exam_name, -- 시험명 e.exam_date, -- 시험일시 e.total_score, -- 만점 c.class_id, -- 반 ID c.class_name, -- 반 이름 g.grade_id, -- 성적 ID g.student_id, -- 학생 ID u.name AS student_name, -- 학생 이름 s.student_no, -- 학생 관리번호 g.score, -- 점수 g.rank_no, -- 석차 g.comment -- 비고 FROM grades g JOIN exams e ON e.exam_id = g.exam_id JOIN classes c ON c.class_id = e.class_id JOIN students s ON s.student_id = g.student_id JOIN users u ON u.user_id = s.user_id
e.subject ILIKE CONCAT('%', #{subject}, '%')
AND e.class_id = #{classId}
AND g.student_id = #{studentId}
ORDER BY e.subject, e.exam_date DESC, e.exam_id DESC, c.class_name, u.name
